// Entry point for both Workers. The same build runs as the public site and as the staff site;
// SITE_MODE decides which routes answer.
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from './.open-next/worker.js'

const STAFF_ROUTES = /^\/(admin|api|teach|svc\/staff)(\/|$)/

export default {
  async fetch(request, env, ctx) {
    const { pathname } = new URL(request.url)
    if (env.SITE_MODE === 'public' && STAFF_ROUTES.test(pathname)) {
      return new Response('Not found', { status: 404 })
    }
    return handler.fetch(request, env, ctx)
  },
} satisfies ExportedHandler<CloudflareEnv>
